import importlib.util, io, sys, types, contextlib
spec = importlib.util.spec_from_file_location("chk", "scripts/check_interface_impl.py")
chk = importlib.util.module_from_spec(spec); spec.loader.exec_module(chk)

# 契约里把接口和两个实现类名都声明出来（= 教练若选「以 contracts 为准并登记实现类」那条路）
CONTRACT = '''
import abc
class Thing(abc.ABC):
    @abc.abstractmethod
    def do(self, a, b=3): ...
class DirectProvider:
    def do(self, a, b=3): return None
class ReservedProvider:
    def do(self, a, b=3): raise NotImplementedError("预留位")
    def acquire(self, account_id): raise NotImplementedError("预留位")
'''
IMPL = '''
class Thing:
    def do(self, a, b=3): return None
class DirectProvider(Thing): pass
class ReservedProvider:
    def do(self, a, b=3): raise NotImplementedError("预留位")
    def acquire(self, account_id): raise NotImplementedError("预留位")
def create_provider(mode=None):
    if mode not in (None, "direct"): raise ValueError("bad mode")
    return DirectProvider()
'''
def fake(name, src):
    mod = types.ModuleType(name); exec(src, mod.__dict__); sys.modules[name] = mod; return mod
fake("synth_contract", CONTRACT); fake("synth_impl", IMPL)
chk.CONTRACT_MODULES = ("synth_contract",); chk.IMPL_PACKAGE = "synth_impl"
chk.PAIRINGS = {"Thing": ["Thing", "DirectProvider", "ReservedProvider"]}; chk.fail_count = 0
buf = io.StringIO()
with contextlib.redirect_stdout(buf):
    code = chk.main()
print(buf.getvalue().rstrip())
print(f"\n  [{'ok' if code == 0 else 'FAIL'}] 契约登记实现类名 + 实现对齐签名 → exit {code}，A2 可满足，脚本不是永远红")
EOF

