import ast, sys
for path in ["price_watch/matcher.py","price_watch/price_engine.py","price_watch/comparator.py","tests/test_price_engine.py","tests/test_comparator.py"]:
    src=open(path,encoding="utf-8").read(); tree=ast.parse(src)
    imported=set()
    for n in ast.walk(tree):
        if isinstance(n, ast.Import):
            imported |= {a.asname or a.name.split('.')[0] for a in n.names}
        elif isinstance(n, ast.ImportFrom) and n.module != "__future__":
            imported |= {a.asname or a.name for a in n.names}
    used={n.id for n in ast.walk(tree) if isinstance(n, ast.Name)} | {n.attr for n in ast.walk(tree) if isinstance(n, ast.Attribute)}
    used |= {getattr(x.value,'id',None) for x in ast.walk(tree) if isinstance(x, ast.Attribute)}
    for n in ast.walk(tree):
        if isinstance(n, ast.Attribute) and isinstance(n.value, ast.Name): used.add(n.value.id)
    dead=sorted(i for i in imported if i not in used and i not in src.split())
    missing=[i for i in sorted(imported-used) if i in src]
    print(f"{path:34} 可疑未用: {missing or '—'}")
PY
